// Package webui embeds the built web graph explorer (web/) so `pudl ui` can
// serve it from the binary. The bundle in static/ is generated by `make web`
// (Vite) and committed; building pudl needs no Node toolchain. `make
// check-web` verifies the committed bundle matches web/src.
package webui

import (
	"embed"
	"io/fs"
)

//go:embed all:static
var static embed.FS

// Assets is the built UI: index.html at the root, hashed bundles in assets/.
func Assets() fs.FS {
	sub, err := fs.Sub(static, "static")
	if err != nil {
		panic(err) // the embed pattern guarantees the directory exists
	}
	return sub
}
